import{_ as t,a}from"./chunks/ugso_whatsapp_action.C0zYnHbc.js";import{_ as s,o,c as r,a3 as i}from"./chunks/framework.BlfGB29P.js";const n="/assets/callmebot/fr.png",l="/assets/callmebot/profiles-fr.png",v=JSON.parse('{"title":"CallMeBot Whatsapp","description":"Messages texte WhatsApp depuis Home Assistant avec profils de destinataire et Blockly.","frontmatter":{"title":"CallMeBot Whatsapp","description":"Messages texte WhatsApp depuis Home Assistant avec profils de destinataire et Blockly."},"headers":[],"relativePath":"fr/projects/callmebot/index.md","filePath":"fr/projects/callmebot/index.md","lastUpdated":1793126212000}'),c={name:"fr/projects/callmebot/index.md"};function p(u,e,d,m,f,g){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="callmebot-whatsapp" tabindex="-1">CallMeBot Whatsapp <a class="header-anchor" href="#callmebot-whatsapp" aria-label="Permalink to &quot;CallMeBot Whatsapp&quot;">​</a></h1><p>Depuis 0.1.5, l’application s’appelle <strong>CallMeBot Whatsapp</strong>. Profils, sujets MQTT et IDs existants sont conservés. <a href="./../callmebot-signal/">CallMeBot Signal</a> utilise ses propres profils et clés.</p><p><strong>Application HA bêta 0.1.6</strong> dans le <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/callmebot" target="_blank" rel="noreferrer">même dépôt que Blocks for HA</a>. Interface et blocs complets en <strong>DE/EN/FR</strong>, langue système et apparence claire/sombre/système. Inspiré de <a href="https://github.com/ioBroker/ioBroker.whatsapp-cmb" target="_blank" rel="noreferrer">ioBroker.whatsapp-cmb</a> ; implémentation UGSo originale sans ioBroker.</p><p><strong>Correction 0.1.1 :</strong> L’envoi fonctionne sans <code>crypto.randomUUID</code>, notamment avec Ingress en HTTP. Redémarrer l’application et recharger la page après la mise à jour. Les identifiants utilisent des octets aléatoires disponibles ou un horodatage avec compteur ; ils détectent les doublons et ne servent pas à l’authentification.</p><p><img src="'+n+'" alt="Interface CallMeBot en français"></p><h2 id="installation-et-configuration" tabindex="-1">Installation et configuration <a class="header-anchor" href="#installation-et-configuration" aria-label="Permalink to &quot;Installation et configuration&quot;">​</a></h2><ol><li>Ajouter <code>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</code> au magasin d’applications HA.</li><li>Installer <strong>CallMeBot Whatsapp</strong>, configurer le courtier MQTT et démarrer l’application.</li><li>Ouvrir l’interface Ingress. Les identifiants MQTT du Supervisor sont prioritaires ; les options de l’application servent de secours.</li><li>Activer son propre destinataire avec le numéro actuel du bot dans le <a href="https://www.callmebot.com/blog/free-api-whatsapp-messages/" target="_blank" rel="noreferrer">guide officiel</a>. Envoyer exactement <code>I allow callmebot to send me messages</code>.</li><li>Enregistrer l’ID du profil, son nom, le numéro activé <strong>avec + et indicatif international</strong>, ainsi que sa clé API. Choisir un profil par défaut. Maximum 16 profils.</li><li>Le bouton de test envoie réellement au profil enregistré sélectionné ; une sélection vide utilise le profil par défaut.</li></ol><p>Un champ de clé vide conserve la clé enregistrée. Les clés ne sont jamais renvoyées à l’interface. Elles restent dans <code>/data/profiles.json</code>, hors Blockly, messages MQTT, stockage du navigateur et journaux. Ce fichier n’est pas chiffré et figure dans les sauvegardes HA.</p><h2 id="bloc-blockly-callmebot" tabindex="-1">Bloc Blockly CallMeBot <a class="header-anchor" href="#bloc-blockly-callmebot" aria-label="Permalink to &quot;Bloc Blockly CallMeBot&quot;">​</a></h2><h3 id="choisir-les-profils-enregistres" tabindex="-1">Choisir les profils enregistrés <a class="header-anchor" href="#choisir-les-profils-enregistres" aria-label="Permalink to &quot;Choisir les profils enregistrés&quot;">​</a></h3><p>Avec <strong>CallMeBot 0.1.2 et Blocks for HA 0.1.69</strong>, le champ de profil ouvre une liste consultable des noms, identifiants et du destinataire par défaut. <strong>Actualiser</strong> recharge la liste. Le bloc affiche le nom ; projets et YAML conservent l’ID original. Un ID vide utilise le destinataire par défaut actuel.</p><p><img src="'+l+'" alt="Sélecteur de profil CallMeBot en français"></p><p>Mettre à jour et redémarrer les deux applications, puis recharger Blocks. HA doit être connecté au courtier et activer la découverte MQTT avec le préfixe standard <code>homeassistant</code>. CallMeBot découvre un capteur de diagnostic, normalement <code>sensor.ugso_callmebot_profiles</code> ; Blocks lit son catalogue via sa connexion HA existante. Le capteur peut être renommé, car son marqueur identifie le catalogue. Base technique : <a href="https://www.home-assistant.io/integrations/sensor.mqtt/" target="_blank" rel="noreferrer">capteurs MQTT HA et attributs JSON</a>.</p><p>Le catalogue retenu <code>ugso/callmebot/profiles</code> contient uniquement IDs, noms, profil par défaut, nombre et marqueur. Aucun numéro, message ou clé API n’est publié. Modifications et reconnexions MQTT actualisent le catalogue. Les noms sont visibles dans MQTT et HA.</p><p>Si l’application, MQTT, la découverte ou la connexion HA est indisponible, la saisie manuelle et le destinataire par défaut restent utilisables. Les IDs supprimés ne sont jamais remplacés automatiquement ; l’application refuse l’envoi vers un profil absent.</p><p>Depuis <strong>Blocks for HA 0.1.68</strong>, dans <strong>Messages → WhatsApp · CallMeBot</strong>.</p><p><img src="'+t+'" alt="Bloc CallMeBot"></p><p>Indiquer l’ID du profil ou laisser vide pour le profil par défaut. Connecter texte, variable ou Jinja comme message. Journal : erreurs seulement, aucun ou info. Exporte <code>mqtt.publish</code> et sérialise le JSON après évaluation du modèle pour conserver correctement guillemets et sauts de ligne.</p><p>MQTT doit être configuré dans HA. Les projets JSON conservent le bloc dédié. Le YAML est réimporté comme action HA/MQTT générale.</p><h2 id="alternative-integration-whatsapp-existante" tabindex="-1">Alternative : intégration WhatsApp existante <a class="header-anchor" href="#alternative-integration-whatsapp-existante" aria-label="Permalink to &quot;Alternative : intégration WhatsApp existante&quot;">​</a></h2><p><img src="'+a+'" alt="Bloc de l’intégration WhatsApp"></p><p>Le deuxième bloc appelle <a href="https://faserf.github.io/ha-whatsapp/services.html" target="_blank" rel="noreferrer">l’intégration WhatsApp de FaserF</a>. Configurer une fois l’URL de son application et le <strong>jeton API fourni par l’application WhatsApp</strong> dans HA. L’intégration gère ce jeton ; le bloc n’en a pas besoin.</p><p>Choisir <code>whatsapp.send_message · number</code> pour l’ancien format, <code>whatsapp.send_message · target</code> selon la documentation actuelle ou <code>notify.whatsapp</code> si configuré. Destinataire : <strong>indicatif international sans +</strong>. Message : texte/Jinja. Le compte facultatif est exporté uniquement avec <code>whatsapp.send_message</code>. Le YAML compatible est importé comme bloc dédié ; les options supplémentaires restent dans l’action HA générale.</p><p>Cette alternative ne nécessite ni application CallMeBot ni clé CallMeBot. L’intégration existante assure l’installation et la connexion WhatsApp.</p><h2 id="protocole-mqtt-et-limites" tabindex="-1">Protocole MQTT et limites <a class="header-anchor" href="#protocole-mqtt-et-limites" aria-label="Permalink to &quot;Protocole MQTT et limites&quot;">​</a></h2><ul><li>Envoi : <code>ugso/callmebot/send</code>, QoS 0, <strong>retain false</strong>.</li><li>Données : <code>{&quot;profile&quot;:&quot;default&quot;,&quot;message&quot;:&quot;Bonjour depuis HA&quot;,&quot;loglevel&quot;:&quot;errors&quot;}</code>. Profil vide/absent : destinataire par défaut.</li><li><code>request_id</code> facultatif : détection des doublons pendant une heure par profil, maximum 1000 identifiants.</li><li>Résultat : <code>ugso/callmebot/result</code>, non retenu, profil, ID de requête, état et horodatage ; sans message ni clé.</li><li>Disponibilité : <code>ugso/callmebot/availability</code>, <code>online</code>/<code>offline</code> retenu pour la connexion au courtier.</li><li>Maximum 4000 caractères, file de 20 commandes, au moins 10 secondes entre les tentatives par profil. Les commandes trop rapides sont refusées, sans délai.</li><li>Sans répétition automatique ni reprise après redémarrage. Les commandes d’envoi retenues sont refusées.</li><li>Un espace MQTT et un ID client : une instance par courtier. Limiter les droits d’écriture sur le sujet d’envoi. Le broker interne reste le réglage par défaut ; MQTT externe avec TLS vérifié est facultatif.</li></ul><p>CallMeBot Free est destiné aux textes personnels vers ses propres numéros activés. Sans groupes, médias, réponses ni confirmation de livraison. <code>accepted</code> confirme seulement l’acceptation API. Numéro, clé et texte sont transmis par HTTPS à CallMeBot. Source : <a href="https://www.callmebot.com/blog/free-api-whatsapp-messages/" target="_blank" rel="noreferrer">activation et API CallMeBot</a>.</p><h2 id="verification" tabindex="-1">Vérification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Vérification&quot;">​</a></h2><p>Build et démarrage Docker, backend avec fournisseur simulé, protocole MQTT, interface DE/EN/FR, affichage mobile et export Blockly vérifiés. Livraison WhatsApp réelle et installation sous HA Supervisor restent à vérifier avec sa propre configuration. Aucun message réel n’a été envoyé.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/callmebot" target="_blank" rel="noreferrer">Code source et commandes de test</a> · Apache-2.0 · Projet communautaire indépendant.</p><h2 id="beta-historique-sauvegarde-des-profils-et-mqtt-tls" tabindex="-1">Bêta : historique, sauvegarde des profils et MQTT TLS <a class="header-anchor" href="#beta-historique-sauvegarde-des-profils-et-mqtt-tls" aria-label="Permalink to &quot;Bêta : historique, sauvegarde des profils et MQTT TLS&quot;">​</a></h2><p>L’historique conserve jusqu’à 200 entrées : date, ID du profil, source et résultat. Filtrer par profil/erreur et confirmer l’effacement. Sans messages, numéros, clés API ni ID de requête. Acceptée signifie acceptation par le fournisseur, pas confirmation de livraison. Une erreur de stockage ne provoque aucun renvoi automatique.</p><p>La sauvegarde chiffre les profils, numéros, clés API et destinataire par défaut avec AES-GCM et une clé dérivée du mot de passe (scrypt). Au moins 12 caractères ; conserver le mot de passe séparément. Il n’est pas enregistré. Restaurer nécessite le mot de passe, une confirmation et un contenu valide. Mot de passe incorrect, fichier altéré ou sauvegarde de l’autre application : profils inchangés. Les envois en attente bloquent la restauration. Identifiants MQTT et historique exclus ; utiliser une sauvegarde complète HA pour ceux-ci.</p><p>Le broker HA automatique reste le réglage existant. Désactiver l’automatisme pour définir un broker externe, son port et ses identifiants. TLS vérifie certificat et nom d’hôte ; import PEM de CA et certificat/clé client possible. Choisir le port TLS, souvent 8883. Champs secrets vides : valeurs enregistrées conservées. HA/Blocks doit utiliser ce broker ou transférer les topics d’envoi/résultat/profils/discovery entre brokers ; aucune passerelle automatique.</p><p>profiles.json, profils, clés, topics MQTT et ID d’entités conservés. Historique : /data/history.json ; réglages MQTT explicitement enregistrés : /data/mqtt.json. Aucune réécriture automatique lors de la mise à jour. Interface DE/EN/FR.</p><p>L’interface et la description portent Bêta. HA n’accepte pas beta comme stage natif ; experimental reste donc la valeur technique valide. <a href="https://developers.home-assistant.io/docs/apps/configuration/" target="_blank" rel="noreferrer">Configuration HA</a>.</p>',36)])])}const q=s(c,[["render",p]]);export{v as __pageData,q as default};
